import{_ as a,o,c as r,a2 as s}from"./chunks/framework.1C62pOns.js";const t="/pro-agent-hub-installer/capturas/pt/grupos-detalhe.png",i="/pro-agent-hub-installer/capturas/pt/usuarios-detalhe.png",n="/pro-agent-hub-installer/capturas/pt/configuracoes.png",d="/pro-agent-hub-installer/capturas/pt/consumo-tokens.png",u="/pro-agent-hub-installer/capturas/pt/import-export.png",f=JSON.parse('{"title":"Administração","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/administracao.md","filePath":"pt/interface/administracao.md","lastUpdated":1787856241000}'),p={name:"pt/interface/administracao.md"};function c(m,e,l,g,h,q){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="administracao" tabindex="-1">Administração <a class="header-anchor" href="#administracao" aria-label="Permalink to &quot;Administração&quot;">​</a></h1><p>Tudo nesta página é visível apenas para usuários <strong>master</strong>.</p><h2 id="grupos" tabindex="-1">Grupos <a class="header-anchor" href="#grupos" aria-label="Permalink to &quot;Grupos&quot;">​</a></h2><p><img src="'+t+'" alt="grupos-detalhe"></p><p>Grupo é a unidade de acesso da plataforma. Ele reúne usuários de um lado e libera recursos do outro: agentes, times, workflows, planejadores, serviços MCP e Apps.</p><p>Cada liberação tem um <strong>modo</strong>:</p><ul><li><strong>Leitura</strong> — abrir e executar.</li><li><strong>Escrita</strong> — abrir, executar e salvar.</li></ul><p>Um usuário pode estar em vários grupos; ele enxerga a união do que os grupos dele liberaram, com o modo mais permissivo entre eles.</p><div class="tip custom-block"><p class="custom-block-title">Um usuário sem grupo não vê nada</p><p>E isso é o comportamento correto, não um defeito. Quem se cadastra sozinho pela tela de criar conta entra sem grupo nenhum, e depende de um master para começar a usar.</p></div><h2 id="usuarios" tabindex="-1">Usuários <a class="header-anchor" href="#usuarios" aria-label="Permalink to &quot;Usuários&quot;">​</a></h2><p><img src="'+i+'" alt="usuarios-detalhe"></p><p>Nome, e-mail, telefone, senha e duas marcações que decidem muita coisa:</p><p><strong>Master</strong> — enxerga tudo e administra tudo, sem passar por grupo. Master não é &quot;usuário avançado&quot;: é quem pode ler chave de API, mudar configuração e exportar a base. Distribua com parcimônia.</p><p><strong>Desabilitado</strong> — o usuário para de entrar, mas continua existindo, e com ele o histórico de execuções e conversas. É o que se usa quando alguém sai da empresa; excluir apagaria o rastro.</p><h2 id="configurações" tabindex="-1">Configurações <a class="header-anchor" href="#configurações" aria-label="Permalink to &quot;Configurações {#configurações}&quot;">​</a></h2><p><img src="'+n+'" alt="configuracoes"></p><h3 id="e-mail" tabindex="-1">E-mail <a class="header-anchor" href="#e-mail" aria-label="Permalink to &quot;E-mail&quot;">​</a></h3><p>O SMTP que a plataforma usa para &quot;esqueci a senha&quot; e para os avisos de consumo. Enquanto não estiver configurado, essas duas coisas simplesmente não saem.</p><h3 id="licenca" tabindex="-1">Licença <a class="header-anchor" href="#licenca" aria-label="Permalink to &quot;Licença&quot;">​</a></h3><p>Número de série e de controle da instalação.</p><h3 id="variaveis-de-ambiente" tabindex="-1">Variáveis de ambiente <a class="header-anchor" href="#variaveis-de-ambiente" aria-label="Permalink to &quot;Variáveis de ambiente&quot;">​</a></h3><p>Pares nome/valor disponíveis para o código de workflows, planejadores, ferramentas MCP e backends de App. É onde ficam chaves e endereços que você não quer escritos no meio do código — e que mudam de um ambiente para outro.</p><h3 id="seguranca" tabindex="-1">Segurança <a class="header-anchor" href="#seguranca" aria-label="Permalink to &quot;Segurança&quot;">​</a></h3><p><strong>Token de API dos workflows</strong> — o segredo que autentica quem dispara um workflow de fora da plataforma.</p><p><strong>Pegasus</strong> — o co-pilot interno. Ligado, ele aparece nas telas de código e de fonte de dados, sugerindo Python, fluxos e seletores CSS. Exige um modelo escolhido; sem modelo, a plataforma recusa salvar com ele ligado.</p><h3 id="retencao" tabindex="-1">Retenção <a class="header-anchor" href="#retencao" aria-label="Permalink to &quot;Retenção&quot;">​</a></h3><p>Quanto histórico de execução guardar. São três limites, aplicados por uma limpeza periódica:</p><table tabindex="0"><thead><tr><th>Limite</th><th>Padrão</th><th>O que faz</th></tr></thead><tbody><tr><td>Dias de execução</td><td>30</td><td>Remove execuções mais antigas que isso.</td></tr><tr><td>Dias de log</td><td>7</td><td>Remove o log detalhado, <strong>mantendo o cabeçalho</strong> da execução.</td></tr><tr><td>Execuções por workflow</td><td>200</td><td>Corta o excedente do workflow que roda muito.</td></tr></tbody></table><p>Os dois primeiros combinam bem: você continua vendo que uma execução de 20 dias atrás rodou e quanto durou, sem carregar o log linha a linha dela.</p><p>Execuções <strong>ainda em andamento nunca são podadas</strong>, por mais antigas que estejam.</p><p>Aqui também fica o <strong>nível de log padrão</strong> dos workflows novos.</p><h2 id="consumo-de-tokens" tabindex="-1">Consumo de tokens <a class="header-anchor" href="#consumo-de-tokens" aria-label="Permalink to &quot;Consumo de tokens {#consumo-de-tokens}&quot;">​</a></h2><p><img src="'+d+'" alt="consumo-tokens"></p><p>Quanto cada modelo consumiu, em tokens e em custo, com relatório diário e mensal.</p><p>O custo depende do preço cadastrado no modelo. Sem preço, você vê contagem de tokens e nenhum valor — o que já serve para achar o agente que está gastando demais.</p><p>O alerta e o bloqueio por teto são configurados <strong>no cadastro do modelo</strong>, não aqui. Ver <a href="/pro-agent-hub-installer/pt/interface/provedores-modelos#preco-e-limites">Provedores e modelos</a>.</p><h2 id="importar-e-exportar" tabindex="-1">Importar e exportar <a class="header-anchor" href="#importar-e-exportar" aria-label="Permalink to &quot;Importar e exportar {#importar-e-exportar}&quot;">​</a></h2><p><img src="'+u+'" alt="import-export"></p><p>Copia cadastros entre ambientes — de desenvolvimento para produção, ou de uma instalação para outra.</p><p>A seleção é uma árvore: escolha grupos inteiros (Workflows, Agentes, Provedores…) ou registros específicos dentro de cada um.</p><h3 id="dependencias-vem-junto" tabindex="-1">Dependências vêm junto <a class="header-anchor" href="#dependencias-vem-junto" aria-label="Permalink to &quot;Dependências vêm junto&quot;">​</a></h3><p>Um agente sem o modelo dele não funciona. Por isso, ao exportar (e ao importar), <strong>os registros dos quais a sua seleção depende são incluídos mesmo que você não os marque</strong> — a menos que você desligue a opção. Marcar um workflow traz o agente que ele chama, o modelo daquele agente e o provedor daquele modelo.</p><p>A tela mostra, antes de confirmar, o que foi acrescentado por dependência.</p><h3 id="na-importacao" tabindex="-1">Na importação <a class="header-anchor" href="#na-importacao" aria-label="Permalink to &quot;Na importação&quot;">​</a></h3><p>O que já existe no destino é <strong>reconhecido pela descrição</strong>, não pelo ID. Um registro existente é mantido como está, e os vínculos apontam para ele — os IDs do arquivo são remapeados para os do destino.</p><p>Isso significa que reimportar não desfaz um ajuste feito à mão no destino. É deliberado: importação é para trazer o que falta, não para sobrescrever o ambiente.</p><div class="warning custom-block"><p class="custom-block-title">Grupos e usuários exigem atenção</p><p>Trazer grupos e usuários de outro ambiente reescreve quem tem acesso ao quê. A tela marca esses grupos e pede confirmação — leia o resumo antes de aceitar.</p></div><div class="warning custom-block"><p class="custom-block-title">Os segredos vão cifrados — mas com uma chave que está no código</p><p>Chaves de API dos provedores, senhas de conexão de banco, senha do SMTP, tokens de webhook e as variáveis de ambiente saem cifradas no arquivo. Só que a chave padrão está no código-fonte: isso protege contra a leitura casual de quem abrir o JSON, <strong>não</strong> contra alguém decidido.</p><p>Para que o arquivo seja de fato confidencial, defina a variável de ambiente <code>PRO_AI_EXPORT_SECRET</code> nas duas instalações. Com ela, o arquivo só abre onde o mesmo valor está configurado — e um arquivo com a chave errada é recusado com mensagem clara, em vez de gravar lixo no lugar da senha.</p><p>De todo modo: o arquivo de exportação é material sensível. Guarde-o como tal e apague-o depois de importar.</p></div>',48)])])}const b=a(p,[["render",c]]);export{f as __pageData,b as default};
